// ─── CUSTOM CURSOR ────────────────────────────────────────────────────────────
const Cursor = () => {
  const dotRef  = useRef(null);
  const ringRef = useRef(null);

  useEffect(() => {
    let raf;
    let mx = 0, my = 0;
    let rx = 0, ry = 0;

    const onMove = e => { mx = e.clientX; my = e.clientY; };
    window.addEventListener('mousemove', onMove);

    const tick = () => {
      rx += (mx - rx) * 0.15;
      ry += (my - ry) * 0.15;
      if (dotRef.current)  { dotRef.current.style.left  = mx + 'px'; dotRef.current.style.top  = my + 'px'; }
      if (ringRef.current) { ringRef.current.style.left = rx + 'px'; ringRef.current.style.top = ry + 'px'; }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => { window.removeEventListener('mousemove', onMove); cancelAnimationFrame(raf); };
  }, []);

  return (
    <>
      <div ref={dotRef}  className="cursor-dot" />
      <div ref={ringRef} className="cursor-ring" />
    </>
  );
};

// ─── LOADING SCREEN ───────────────────────────────────────────────────────────
const LoadingScreen = ({ onComplete }) => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
      setProgress(p => {
        if (p >= 100) { clearInterval(interval); setTimeout(onComplete, 400); return 100; }
        return p + Math.random() * 4 + 1;
      });
    }, 40);
    return () => clearInterval(interval);
  }, [onComplete]);

  return (
    <motion.div
      className="fixed inset-0 z-[9999] flex flex-col items-center justify-center"
      style={{ background: '#000' }}
      exit={{ opacity: 0, scale: 1.02 }}
      transition={{ duration: 0.8, ease: [0.76,0,0.24,1] }}
    >
      {/* Pulse rings */}
      <div className="absolute" style={{ width: 200, height: 200 }}>
        {[0,1,2].map(i => (
          <div key={i} className="absolute inset-0 rounded-full border border-white/10 pulse-ring"
               style={{ animationDelay: `${i * 0.7}s` }} />
        ))}
      </div>

      {/* Logo */}
      <motion.div
        className="relative z-10 flex flex-col items-center gap-4"
        initial={{ opacity: 0, scale: 0.8 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.6 }}
      >
        <img src={IMG_SPACE} alt="RenderScale Studio"
             style={{ width: 280, height: 'auto', objectFit: 'contain', objectPosition: 'center' }} />

        {/* Progress bar */}
        <div className="mt-8 relative" style={{ width: 200 }}>
          <div className="h-px bg-white/10 rounded-full overflow-hidden">
            <motion.div className="h-full bg-white rounded-full"
                         style={{ width: `${progress}%`, transition: 'width 0.1s' }} />
          </div>
          <div className="mt-3 text-center font-body text-white/40 text-xs tracking-[0.3em] uppercase">
            {Math.min(100, Math.round(progress))}%
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

// ─── PARALLAX BG ──────────────────────────────────────────────────────────────
const ParallaxBg = ({ src, overlay = 'rgba(0,0,0,0.55)', children, className = '' }) => {
  const ref = useRef(null);
  const rafRef = useRef(null);
  const bgRef = useRef(null);

  useEffect(() => {
    const el = ref.current;
    const bg = bgRef.current;
    if (!el || !bg) return;

    let currentScale = 1, targetScale = 1;
    let currentY = 0, targetY = 0;

    const tick = () => {
      const rect = el.getBoundingClientRect();
      const vh   = window.innerHeight;
      const visible = rect.top < vh && rect.bottom > 0;

      if (visible) {
        const progress = (vh - rect.top) / (vh + rect.height);
        targetScale = 1 + progress * 0.08;
        targetY     = (progress - 0.5) * 60;
      }

      currentScale += (targetScale - currentScale) * 0.04;
      currentY     += (targetY     - currentY    ) * 0.04;

      bg.style.transform = `scale(${currentScale}) translateY(${currentY}px)`;
      rafRef.current = requestAnimationFrame(tick);
    };
    rafRef.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafRef.current);
  }, []);

  return (
    <div ref={ref} className={`relative overflow-hidden ${className}`}>
      <div ref={bgRef} className="section-bg"
           style={{ backgroundImage: `url(${src})`, willChange: 'transform' }} />
      <div className="absolute inset-0" style={{ background: overlay }} />
      <div className="absolute inset-0" style={{
        background: 'radial-gradient(ellipse 80% 60% at 50% 50%, rgba(60,100,200,0.06) 0%, transparent 70%)'
      }} />
      {children}
    </div>
  );
};

// ─── ANIMATED COUNTER ─────────────────────────────────────────────────────────
const Counter = ({ target, suffix = '' }) => {
  const [count, setCount] = useState(0);
  const ref  = useRef(null);
  const seen = useRef(false);
  const inView = useInView(ref, { once: true, margin: '-80px' });

  useEffect(() => {
    if (!inView || seen.current) return;
    seen.current = true;
    const num = parseFloat(target.replace(/[^0-9.]/g, ''));
    const duration = 1800;
    const start = performance.now();
    const raf = () => {
      const elapsed = performance.now() - start;
      const progress = Math.min(elapsed / duration, 1);
      const ease = 1 - Math.pow(1 - progress, 3);
      setCount(+(num * ease).toFixed(num < 10 ? 1 : 0));
      if (progress < 1) requestAnimationFrame(raf);
    };
    requestAnimationFrame(raf);
  }, [inView, target]);

  return (
    <span ref={ref}>
      {count}{suffix}
    </span>
  );
};

